"""Create a detailed comparison DOCX from the already saved measurement snapshot."""
import json
from pathlib import Path
from datetime import datetime,timezone,timedelta
root=Path(__file__).resolve().parents[1]
snapshot=root/'reports/SauKhiToiUu/Evaluation_App_2026-11-04_135119.json'
data=json.loads(snapshot.read_text(encoding='utf-8-sig'))
data['measurement_snapshot_at']=data['captured_at']
data['captured_at']=datetime.now(timezone(timedelta(hours=7))).isoformat(timespec='seconds')
data['comparison_source_snapshot']=str(snapshot.relative_to(root))
source=(root/'scripts/write_optimization_report.py').read_text(encoding='utf-8-sig')
start=source.index('\nimport json, zipfile, hashlib, math\n')
end=source.index("E=data['optimization']; B=E['before']; A=E['after']")
utilities=source[start:end].replace("Path.cwd()/'reports'/'SauKhiToiUu'","root/'reports'/'SauKhiToiUu'")
utilities=utilities.replace("'Evaluation_App_'","'ThongKe_SoSanh_Truoc_Sau_ToiUu_'")
packaging=source[source.index("sec=el(body,'sectPr')"):]
packaging=packaging.replace("'Trước / sau tối ưu'","'Kết quả tối ưu ứng dụng'")
packaging=packaging.replace('Đánh giá tối ưu - Ứng dụng nhận diện tiền Việt Nam','Thống kê so sánh trước và sau tối ưu ứng dụng')
packaging=packaging.replace('Project baseline','Thống kê so sánh')
CONTENT = "\nE=data['optimization'];B=E['before'];A=E['after'];ab=E['apk_before'];aa=E['apk_after']\nbefore=E['benchmark_before'];runs=E['benchmark_after_runs']\ndef num(x,places=2):return f'{x:,.{places}f}'.replace(',',' ').replace('.',',')\ndef signed(x,unit=''):return ('+' if x>0 else '')+num(x)+(' '+unit if unit else '')\ndelta_apk=aa['MiB']-ab['MiB'];delta_ms=A['median_ms']-B['median_ms']\ndata['comparison_calculations']={\n 'apk_change_mib':delta_apk,'median_change_ms':delta_ms,\n 'p95_change_ms':A['p95_ms']-B['p95_ms'],'rss_change_mib':A['rss_mean_mib']-B['rss_mean_mib'],\n 'rate_active_config_fps':1000/120,'rate_empty_config_fps':1000/300,\n 'rate_locked_config_fps':1000/240,\n 'note':'These are recalculations of the saved measurement snapshot, not new benchmark runs.'}\ntitle('THỐNG KÊ SO SÁNH TRƯỚC / SAU','Kết quả tối ưu ứng dụng','Camera • dung lượng APK • RAM • pin • TTS')\npara('Ứng dụng hỗ trợ người khiếm thị nhận diện tiền Việt Nam.','Subtitle')\npara('Dữ liệu đo đã chốt: 04/11/2026, 13:51:19 (UTC+07). Ngày lập bảng: '+capture,'Meta')\nnote('Báo cáo tổng hợp lại số liệu đã lưu; không phải một lần đo mới. “Trước” là source trước tối ưu; “sau” là pipeline đã triển khai. Mỗi bảng chỉ rõ số đo thực nghiệm, cấu hình hoặc hành vi kiểm thử.')\nh('1. Bảng tổng hợp kết quả')\ntable(['Chỉ số','Trước tối ưu','Sau tối ưu','Chênh lệch / đánh giá'],[\n('APK release ARM64 (MiB)',num(ab['MiB']),num(aa['MiB']),signed(delta_apk,'MiB')+'\\nGiảm '+num(E['apk_reduction_pct'])+'%; tách ABI.'),\n('Xử lý 1 frame: trung vị (ms)',num(B['median_ms']),num(A['median_ms']),signed(delta_ms,'ms')+'\\nGiảm '+num(E['median_reduction_pct'])+'% trong fixture debug.'),\n('Xử lý 1 frame: P95 (ms)',num(B['p95_ms']),num(A['p95_ms']),signed(A['p95_ms']-B['p95_ms'],'ms')+'\\nGiảm '+num(E['p95_reduction_pct'])+'%; có biến động.'),\n('RAM RSS khi liên tục xử lý (MiB)',num(B['rss_mean_mib']),num(A['rss_mean_mib']),signed(A['rss_mean_mib']-B['rss_mean_mib'],'MiB')+'\\nTăng '+num(E['rss_change_pct'])+'%; chưa đạt giảm RAM.'),\n('Pin tiêu hao trong 20 phút','Chưa đo','Chưa đo','Chưa thể tính mức tiết kiệm pin.'),\n('Độ trễ TTS phát ra loa (ms)','Chưa đo','Chưa đo','Test hành vi đạt; chưa có số đo âm thanh.'),\n('Kiểm thử tự động','52 đạt; 5 lỗi test cũ',str(E['tests_passed'])+' đạt','Cập nhật 5 test cũ và bổ sung 24 test; không phải chỉ số tốc độ.'),\n],widths=[2700,1450,1450,4240],font=18)\nh('2. Đánh giá có thể rút ra')\nbullet('APK nhỏ hơn và trung vị xử lý ảnh thấp hơn trong phép thử đã ghi nhận. So sánh APK bao gồm thay đổi cách đóng gói ABI.')\nbullet('RAM RSS lúc xử lý liên tục tăng; không thể kết luận toàn bộ app đã tiết kiệm RAM. Chi phí nạp model cũng cần theo dõi.')\nbullet('Đã triển khai giảm tần suất AI lúc ít hoạt động, ưu tiên câu TTS và giải phóng khi nghỉ. Hiệu quả pin, độ trễ camera/TTS cần đo trên điện thoại.')\nnote('1 MiB = 1 048 576 byte. ms = mili giây. Số phần trăm được tính từ số liệu gốc chưa làm tròn. Tốc độ cấu hình không phải FPS đo trực tiếp của camera.')\n\npage()\ntitle('HẠNG MỤC 1 / CAMERA & AI','Thay đổi trong luồng xử lý','So sánh thiết kế source và kết quả đo detector')\nh('3. Bảng đối chiếu triển khai')\ntable(['Nội dung','Trước tối ưu','Sau tối ưu'],[\n('Worker xử lý AI','Isolate.run tạo công việc isolate cho từng frame.','Duy trì một worker isolate cho cả phiên; chỉ một yêu cầu đang xử lý.'),\n('Truyền ảnh và bộ đệm','Snapshot các plane; cấp phát bộ đệm tiền xử lý theo frame.','TransferableTypedData; tái sử dụng Float32List đầu vào; đọc output từ view tensor.'),\n('Nhịp nhận frame bình thường','Tối thiểu 120 ms/lượt.','Giữ tối thiểu 120 ms/lượt, khoảng 8,33 lượt/giây theo cấu hình.'),\n('Không phát hiện tiền','Nhịp cơ bản 120 ms, ngoài các khoảng tạm dừng khác.','Sau 3 frame không có tiền: 300 ms/lượt, khoảng 3,33 lượt/giây theo cấu hình.'),\n('Đã đọc kết quả / cần chỉnh camera','Có logic tạm dừng phân loại 3,5 giây sau hướng dẫn lặp lại.','Nhịp 240 ms khi khóa kết quả hoặc sau các frame cần chỉnh liên tiếp; bỏ khoảng dừng phân loại 3,5 giây này.'),\n('Webcam không có flash','Có thể phát sinh lỗi “No flash unit” khi tự bật flash.','Kiểm tra FLASH_INFO_AVAILABLE qua Camera2; không dùng auto-flash/lux khi không có đèn.'),\n],widths=[2200,3500,4140],font=18)\nh('4. Tốc độ detector đã đo')\ntable(['Chỉ tiêu','Trước','Sau'],[\n('Số mẫu sau làm nóng','60 frame / 3 vòng','120 frame / 6 vòng, từ 2 lần chạy'),\n('Trung vị thời gian xử lý',num(B['median_ms'])+' ms',num(A['median_ms'])+' ms'),\n('P95 thời gian xử lý',num(B['p95_ms'])+' ms',num(A['p95_ms'])+' ms'),\n('Chữ ký đầu ra của ảnh cố định','60 chữ ký tham chiếu','Mỗi lượt sau khớp cả 60 chữ ký tham chiếu'),\n],widths=[3000,3000,3840],font=18)\nnote('Số đo tính thời gian lời gọi detector cho ảnh cố định; không tính toàn bộ camera → xác nhận 3 frame → phát giọng nói. Khoảng nghỉ 16 ms giữa frame không nằm trong đồng hồ đo. Các khoảng ổn định ánh sáng/flash khác vẫn được giữ.')\nh('5. Đánh đổi cần lưu ý')\npara('Nhịp xử lý chậm hơn khi khóa kết quả có thể làm chậm xác nhận tờ tiền đã rời khung. Cần thử thao tác đưa/rút và chuyển sang tờ tiếp theo. Đầu ra fixture khớp chỉ xác nhận không đổi kết quả trên ảnh thử này; không thay thế đo độ chính xác trên tiền thật.','Note')\n\npage()\ntitle('HẠNG MỤC 2 / BỘ NHỚ','RAM và vòng đời tài nguyên','Tách RSS của benchmark khỏi PSS khi chuyển nền')\nh('6. RSS trong bài xử lý liên tục — so sánh trước/sau')\ntable(['Nội dung','Trước','Sau'],[\n('RSS trung bình các mốc cuối vòng',num(B['rss_mean_mib'])+' MiB',num(A['rss_mean_mib'])+' MiB'),\n('Số mốc lấy trung bình','3 mốc','6 mốc'),\n('Chênh lệch','Mốc tham chiếu',signed(A['rss_mean_mib']-B['rss_mean_mib'],'MiB')+'; tăng '+num(E['rss_change_pct'])+'%'),\n],widths=[3600,2600,3640],font=18)\nnote('Chưa đạt mục tiêu giảm RAM lúc suy luận liên tục. Worker/buffer giữ lâu giảm công việc lặp lại nhưng có thể làm tăng bộ nhớ lưu giữ; phép thử hiện tại chưa tách riêng nguyên nhân. RSS không phải riêng RAM của model, cũng không phải RAM đỉnh.')\nh('7. PSS khi xuống nền — chỉ trong bản sau tối ưu')\nphase_names={'active_before_background':'Đang quét, trước xuống nền','background_after_18_seconds':'Ở nền sau 18 giây','resumed_camera_ready':'Quay lại, camera hoạt động'}\nrows=[]\nfor s in E['idle']['samples']:\n rows.append((phase_names.get(s['phase'],s['phase']),num(s['total_pss_kib']/1024),\n              num(s['native_heap_alloc_kib']/1024),'Có' if s['camera_active'] else 'Không'))\ntable(['Trạng thái bản sau','PSS (MiB)','Native heap alloc (MiB)','Camera đang dùng'],rows,\n widths=[3400,1800,2600,2040],font=18)\nactive,bg,resumed=E['idle']['samples']\npara('PSS trong lượt thử này giảm '+num((active['total_pss_kib']-bg['total_pss_kib'])/1024)+' MiB khi xuống nền. Cùng PID xuyên suốt; camera dừng ở nền và hoạt động lại khi trở về app. Đây không phải mức giảm RAM giữa bản cũ và bản mới.','Note')\nh('8. Cơ chế giải phóng và chi phí khởi tạo')\ntable(['Nội dung','Trước','Sau'],[\n('Giữ model khi ngừng quét','Detector được đóng khi backend dispose; chưa có hẹn giải phóng sau 15 giây nghỉ.','Khi stop có release camera: hẹn 15 giây để đóng worker/interpreter; quay lại sớm thì hủy lịch.'),\n('Nạp detector: số quan sát riêng lẻ',num(before['initialize_ms'])+' ms','Lần 1: '+num(runs[0]['initialize_ms'])+' ms\\nLần 2: '+num(runs[1]['initialize_ms'])+' ms'),\n],widths=[2600,3200,4040],font=18)\nnote('Thời gian nạp là các quan sát đơn lẻ, chịu ảnh hưởng cache/tải máy, không phải benchmark cold start. Nạp lại sau nghỉ dài có thể tăng thời gian mở camera. PSS tính tỷ lệ phần bộ nhớ dùng chung; RSS tính các trang đang cư trú. Không lấy PSS trừ RSS hoặc so hai loại này như cùng một chỉ số.')\n\npage()\ntitle('HẠNG MỤC 3 / DUNG LƯỢNG APK','Đóng gói và model AI','Chỉ dùng APK release build mới để đối chiếu')\nh('9. Thống kê artifact')\ntable(['Chỉ tiêu','Trước tối ưu','Sau tối ưu'],[\n('Kích thước byte',f\"{ab['bytes']:,}\".replace(',',' '),f\"{aa['bytes']:,}\".replace(',',' ')),\n('Dung lượng MiB',num(ab['MiB']),num(aa['MiB'])),\n('Dung lượng MB thập phân',num(ab['bytes']/1e6),num(aa['bytes']/1e6)),\n('ABI có thư viện trong APK',', '.join(ab['abis']),', '.join(aa['abis'])),\n('Kích thước model nhúng',f\"{ab['model_bytes']:,} byte\".replace(',',' '),f\"{aa['model_bytes']:,} byte\".replace(',',' ')),\n('Nén model trong ZIP','STORED / không nén','STORED / không nén'),\n('Mức giảm APK','Mốc tham chiếu',num(ab['MiB']-aa['MiB'])+' MiB; giảm '+num(E['apk_reduction_pct'])+'%'),\n],widths=[2800,3400,3640],font=18)\nnote('APK trước nhắm ARM64 nhưng còn thư viện của các ABI khác; APK sau dùng --split-per-abi và chỉ còn ARM64. Mức giảm bao gồm lợi ích tách ABI. Không thể quy toàn bộ mức giảm cho thay đổi thuật toán hoặc R8; đây cũng không phải kích thước một APK dùng chung cho mọi kiến trúc.')\npara('Đã bật rõ minify và shrinkResources trong release; script build xuất APK riêng cho từng ABI. Model không đổi, vẫn float32 và không được nén ZIP. Không sử dụng APK debug 102,24 MB hoặc bản release cũ ngày 16/10 để tính phần trăm giảm.','Note')\nh('10. Kiểm tra tính toàn vẹn bằng SHA-256')\ntable(['Đối tượng','SHA-256'],hashes([\n('Model nguồn / model trong cả hai APK',E['model_sha256']),\n('APK release trước',ab['sha256']),\n('APK release sau',aa['sha256']),\n]),widths=[3400,6440],font=16)\npara('APK trước: '+ab['path'],'Reference')\npara('APK sau: '+aa['path'],'Reference')\nnote('Model, ngưỡng confidence 0,78 và quy tắc xác nhận 3 frame được giữ nguyên. Mức giảm APK không phải mức giảm RAM hoặc pin.')\n\npage()\ntitle('HẠNG MỤC 4 & 5 / TTS VÀ PIN','Hành vi đã đổi, số đo còn thiếu','Không quy số lời gọi native thành độ trễ âm thanh')\nh('11. TTS — đối chiếu source và kiểm thử')\ntable(['Kịch bản','Trước tối ưu','Sau tối ưu'],[\n('3 câu khác nhau, cùng tốc độ, đọc tuần tự','Theo source cũ: mỗi yêu cầu hợp lệ gọi stop và setSpeechRate; 3 câu tương ứng 3 lần mỗi loại.','Test mô phỏng: setSpeechRate 1 lần; không stop thừa giữa 3 câu đã đọc xong.'),\n('Thông báo khi đang đọc mệnh giá','Chưa phân cấp ưu tiên các câu nói.','Kết quả > chỉ dẫn thao tác > hướng dẫn camera > trạng thái. Câu ưu tiên thấp không cắt ngang mệnh giá.'),\n('Câu trùng đang đọc','Chưa gộp yêu cầu cùng câu đang phát.','Gộp câu trùng có cùng tốc độ vào Future đang đọc.'),\n('Kết quả cần ngắt hướng dẫn','Điều phối bằng token yêu cầu.','Giữ cơ chế hủy; cho kết quả ưu tiên cao ngắt hướng dẫn, chỉ tuần tự hóa khâu chuẩn bị native.'),\n('Độ trễ phát âm / chất lượng giọng','Chưa có số đo thiết bị thật.','Chưa có số đo thiết bị thật; không đổi engine để suy ra chất lượng giọng.'),\n],widths=[2400,3200,4240],font=18)\nnote('Bằng chứng sau tối ưu là test với native channel giả lập trong test/services/speech_service_test.dart. “Ít lời gọi hơn” là thay đổi hành vi, không phải chứng minh âm thanh phát nhanh hơn bao nhiêu ms.')\nh('12. Pin — hướng tối ưu và giới hạn kết luận')\ntable(['Nội dung','Trước','Sau / đánh giá'],[\n('Nhịp AI bình thường','120 ms/lượt','Giữ 120 ms/lượt.'),\n('Sau 3 frame không có tiền','Nhịp cơ bản 120 ms/lượt','300 ms/lượt: giới hạn cấu hình 8,33 → 3,33 lượt/giây.'),\n('Khi đã đọc kết quả','Không có cơ chế pacing mới này','240 ms/lượt, khoảng 4,17 lượt/giây theo cấu hình.'),\n('Nền / nghỉ dài','Dừng camera theo vòng đời','Bổ sung hẹn giải phóng model/worker sau 15 giây nghỉ có release camera.'),\n('mAh / % pin / nhiệt độ sau 20 phút','Chưa đo','Chưa đo; chưa thể tính tỷ lệ tiết kiệm pin.'),\n],widths=[2800,2800,4240],font=18)\nnote('Giảm 60% giới hạn tần suất xử lý ở một trạng thái không tương đương giảm 60% pin. Camera, màn hình, flash, TTS và thời gian mỗi lần suy luận vẫn tiêu thụ điện. Cần đo cùng điện thoại, cùng kịch bản và điều kiện.')\n\npage()\ntitle('PHƯƠNG PHÁP & MẪU THÔ','Chi tiết phép thử detector','Số liệu dùng máy ảo debug; không thay thế profile trên điện thoại')\nh('13. Điều kiện đo')\ntable(['Yếu tố','Thiết lập'],[\n('Thiết bị / môi trường','Flutter_API_36, Android 16 / API 36, x86_64; Flutter 3.47.7, Dart 3.13.5; chế độ debug.'),\n('Ảnh đầu vào','YUV420 640 × 480 tổng hợp cố định; xoay 0°, 90°, 180°, 270°. Không phải bộ ảnh tiền thật.'),\n('Model / xử lý','Cùng float32; input [1,3,416,416], output [1,22,3549]; CPU 4 luồng.'),\n('Số mẫu','Trước: 1 lần chạy, 3 × 20 frame. Sau: 2 lần chạy, mỗi lần 3 × 20 frame. Mỗi lần có 5 frame làm nóng.'),\n],widths=[2700,7140],font=18)\nh('14. Kết quả theo từng vòng')\nrr=[]\nfor label,stats in [('Trước',B),('Sau',A)]:\n for r in stats['rounds']:\n  rr.append((label+' '+str(r['round']),'20',num(r['median_ms']),num(r['p95_ms']),num(r['rss_mib'])))\ntable(['Bản / vòng','Mẫu','Trung vị (ms)','P95 (ms)','RSS cuối vòng (MiB)'],rr,\n widths=[1700,700,2200,2200,3040],font=18)\nh('15. Định nghĩa và cách tính')\nbullet('Trung vị: giá trị ở giữa khi sắp xếp toàn bộ mẫu; nếu số mẫu chẵn, lấy trung bình hai mẫu giữa.')\nbullet('P95: mẫu có thứ hạng ceil(0,95 × N). Đây là ngưỡng khoảng 95% mẫu không vượt quá trong tập đo.')\nbullet('RSS trung bình: trung bình các ảnh chụp cuối vòng (3 mốc trước, 6 mốc sau), không phải trung bình theo thời gian hay RAM đỉnh.')\nbullet('Tỷ lệ giảm = (trước − sau) / trước × 100%. Tỷ lệ RAM tăng = (sau − trước) / trước × 100%.')\nnote('Không kiểm soát tải máy chủ, JIT, GC và cache; số lần chạy hai bản không bằng nhau. Các vòng cuối của bản trước đã nhanh hơn các vòng đầu. Số liệu cho thấy cải thiện quan sát được, chưa chứng minh mức tăng tốc ổn định trên mọi thiết bị. Gộp cả hai lượt sau, không chỉ chọn lượt tốt hơn.')\n\npage()\ntitle('KIỂM CHỨNG & NGHIỆM THU','Mục đã đạt và mục cần đo tiếp','Các chỉ số thiếu dữ liệu được ghi rõ để tránh kết luận quá mức')\nh('16. Kiểm tra đã thực hiện')\ntable(['Nội dung','Kết quả / ý nghĩa'],[\n('Unit / widget tests',str(E['tests_passed'])+' đạt. Trước có 52 đạt và 5 lỗi test/fixture cũ; sau cập nhật các test này và thêm 24 ca.'),\n('Phân tích tĩnh',f\"{E['analysis']['errors']} lỗi; {E['analysis']['warnings']} cảnh báo; {E['analysis']['info']} thông tin deprecated của Share/shareXFiles.\"),\n('Android release ARM64','Build thành công; kiểm tra byte, ABI và hash model của APK.'),\n('App chính và vòng đời camera','Chạy được trên máy ảo; camera hoạt động → dừng ở nền → hoạt động lại.'),\n('Web','Build thành công theo log; không coi đây là đo hiệu năng web hoặc xác nhận hỗ trợ Wasm.'),\n],widths=[3000,6840],font=18)\nh('17. Bảng nghiệm thu cần bổ sung trên điện thoại thật')\ntable(['Chỉ số cần đo','Trước','Sau','Điều kiện giữ giống nhau'],[\n('RAM PSS TB / đỉnh (MiB)','Chưa đo','Chưa đo','Cùng máy, cùng chế độ profile/release; tách lúc quét, nền, quay lại.'),\n('Tiêu hao pin 20 phút (mAh hoặc %)','Chưa đo','Chưa đo','Cùng sạc, độ sáng, flash, môi trường và số lần đọc.'),\n('Đưa tiền → bắt đầu đọc (ms)','Chưa đo','Chưa đo','Cùng bộ tiền, lịch đưa/rút và yêu cầu xác nhận 3 frame.'),\n('TTS request → start / ra loa (ms)','Chưa đo','Chưa đo','Cùng engine, giọng, tốc độ; tách callback start và âm thanh thực.'),\n('Đúng mệnh giá / tổng lượt (%)','Chưa đo','Chưa đo','Cùng bộ tiền kiểm thử độc lập, ánh sáng và góc cầm.'),\n],widths=[3000,1100,1100,4640],font=18)\nh('18. Nguồn dữ liệu và lưu trữ')\npara('Mốc Word trước tối ưu: reports/TruocKhiToiUu/Baseline_App_2026-11-04_114840.docx','Reference')\npara('Snapshot dùng lập bảng: reports/SauKhiToiUu/Evaluation_App_2026-11-04_135119.json','Reference')\npara('Mốc source: reports/SauKhiToiUu/before/source-before.zip; Git '+data['commit'],'Reference')\npara('Mẫu thô: reports/SauKhiToiUu/before/detector-benchmark.json; hai JSON benchmark sau được liệt kê đầy đủ trong JSON đi kèm. Tên file lịch sử “compressed/uncompressed” không có nghĩa model thực sự được nén khác nhau: mọi APK đã kiểm tra đều STORED.','Reference')\npara('Log sau tối ưu: reports/SauKhiToiUu/after/{tests.log, analyze.log, build-release-arm64.log, main-smoke.log, web-build.log, idle-memory.json}. JSON đi kèm Word lưu số liệu và công thức tính lại.','Reference')\nnote('Mục tiêu tiếp theo là giảm RAM khi suy luận liên tục và đo pin/TTS trên thiết bị thật. Chưa có cơ sở ghi “cả năm hạng mục đều cải thiện”.')\n"
